+    protected void putEndMessage(MappedFileQueue mappedFileQueue) {
+        MappedFile lastFile = mappedFileQueue.getLastMappedFile();
+        if (!lastFile.isFull()) {
+            lastFile.appendMessage(ByteBuffer.allocate(0), endMsgCallback);
+        }
